// Slack's emoji shortcodes as the emoji themselves, for Relay phone and desktop Reviews. Slack text
// (and the reactions read through the Slack connector) carries `:clapper:`, `:+1::skin-tone-3:`;
// these turn them into 🎬 and 👍🏼. A workspace's custom emoji have no character and stay `:name:`.
//
// Pure module, no dependencies; src/data.ts is generated by build.ts.
import { SLACK_EMOJI } from "./data";

/** Slack's skin tone suffixes as the Fitzpatrick modifiers. */
const SKIN_TONES: Readonly<Record<string, string>> = {
  "skin-tone-2": "\u{1F3FB}",
  "skin-tone-3": "\u{1F3FC}",
  "skin-tone-4": "\u{1F3FD}",
  "skin-tone-5": "\u{1F3FE}",
  "skin-tone-6": "\u{1F3FF}",
};

const SHORTCODE = /:([a-z0-9_+'-]+):(?::(skin-tone-[2-6]):)?/gi;

/** The emoji for one short name (`+1`, `thumbsup`, `clapper`), with an optional tone; null for a custom or unknown one. */
export function slackEmoji(name: string, tone?: string): string | null {
  const base = SLACK_EMOJI[name.toLowerCase()];
  if (base === undefined) return null;
  const modifier = tone === undefined ? undefined : SKIN_TONES[tone.toLowerCase()];
  // A tone replaces the emoji presentation selector (☝️ + 🏽 is ☝🏽).
  return modifier === undefined ? base : `${base.replace(/\uFE0F/g, "")}${modifier}`;
}

/** Shortcodes in `text` as emoji, outside code spans and fences; unknown ones (custom emoji) stay as written. */
export function emojify(text: string): string {
  if (!text.includes(":")) return text;
  // Odd pieces of a split on backtick runs are code: `:not_this:` stays literal.
  return text
    .split(/(`{1,3}[^`]*`{1,3})/)
    .map((part, index) =>
      index % 2 === 1
        ? part
        : part.replace(
            SHORTCODE,
            (whole: string, name: string, tone: string | undefined) =>
              slackEmoji(name, tone) ?? whole,
          ),
    )
    .join("");
}

/** A reaction as the Slack read gives it (`fire`, `+1::skin-tone-2`, `:fire:` or the emoji) as the emoji; a custom one as `:name:`. */
export function reactionEmoji(reaction: string): string {
  return emojify(/^[\w+'-]+(::skin-tone-[2-6])?$/i.test(reaction) ? `:${reaction}:` : reaction);
}
